const app = document.querySelector<HTMLDivElement>('#app')!;
let active = 'Dashboard'; let user: { name: string; email: string } | null = null; let timerSeconds = 25 * 60; let timer: number | undefined; let timerStartedAt = 0;
type ActivityStats = { minutes_this_week:number; quizzes_generated:number; sessions_completed:number; current_streak:number; notes_uploaded:number };
let stats:ActivityStats={minutes_this_week:0,quizzes_generated:0,sessions_completed:0,current_streak:0,notes_uploaded:0};
let focusSubject='';
type Subject = { id: string; name: string };
let subjects: Subject[] = [];
let activeDocument: { id: string; filename: string } | null = null;

const esc = (s: string) => s.replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]!);
function formatMarkdown(markdown:string){
  const inline=(value:string)=>esc(value).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/__(.+?)__/g,'<strong>$1</strong>').replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g,'$1<em>$2</em>').replace(/(^|[^_])_([^_\n]+)_(?!_)/g,'$1<em>$2</em>');
  const lines=markdown.replace(/\r/g,'').split('\n');let html='';let paragraph:string[]=[];let list:'ul'|'ol'|null=null;
  const closeParagraph=()=>{if(paragraph.length){html+=`<p>${paragraph.map(inline).join('<br>')}</p>`;paragraph=[]}};
  const closeList=()=>{if(list){html+=`</${list}>`;list=null}};
  for(const raw of lines){const line=raw.trim();if(!line){closeParagraph();closeList();continue}
    const heading=line.match(/^(#{1,6})\s+(.+)$/);if(heading){closeParagraph();closeList();const level=heading[1].length;html+=`<h${level}>${inline(heading[2])}</h${level}>`;continue}
    if(/^([-*_])\1\1+$/.test(line)){closeParagraph();closeList();html+='<hr>';continue}
    const unordered=line.match(/^[-*+]\s+(.+)$/);const ordered=line.match(/^\d+[.)]\s+(.+)$/);if(unordered||ordered){closeParagraph();const next=unordered?'ul':'ol';if(list!==next){closeList();list=next;html+=`<${list}>`}html+=`<li>${inline((unordered||ordered)![1])}</li>`;continue}
    const quote=line.match(/^>\s?(.+)$/);if(quote){closeParagraph();closeList();html+=`<blockquote>${inline(quote[1])}</blockquote>`;continue}
    closeList();paragraph.push(line);
  }
  closeParagraph();closeList();return html;
}
function render() {
  if (!user) { renderAuth(); return; }
  app.innerHTML = `<div class="shell"><aside class="sidebar"><a class="brand" href="#"><span class="brand-mark">✳</span><span>learnova<span class="brand-period">.</span></span></a><button class="workspace-switch"><span class="avatar avatar-small">${initials(user.name)}</span><span class="workspace-copy"><b>${esc(user.name)}’s space</b><small>Personal workspace</small></span><span class="switch-chevron">⌄</span></button><div class="nav-label">MENU</div><nav class="nav-main">${navItem('Dashboard','⌂')} ${navItem('My Library','▤')} ${navItem('Study Planner','▦')} ${navItem('Progress','◒')}</nav><div class="nav-label tools-label">YOUR TOOLS</div><nav class="nav-tools">${tools.map(t => `<button class="nav-link ${active===t.name?'selected':''}" data-tool="${t.id}"><span class="nav-glyph ${t.color}">${t.icon}</span><span>${t.name}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="upgrade-card"><div class="upgrade-spark">✳</div><b>A little more room<br/>to grow?</b><p>Make every study session count with Learnova Plus.</p><button data-action="upgrade">Explore Plus <span>↗</span></button></div><button class="nav-link settings-link" data-action="settings"><span>⚙</span> Settings</button><button class="profile-button" data-action="profile"><span class="avatar">${initials(user.name)}</span><span class="profile-copy"><b>${esc(user.name)}</b><small>${esc(user.email)}</small></span><span class="dots">•••</span></button></div></aside><main class="main"><header class="topbar"><div class="crumb"><span>My space</span><i>/</i><b>${esc(active)}</b></div><div class="top-actions"><label class="search"><span>⌕</span><input placeholder="Search anything..." /><kbd>⌘ K</kbd></label><button class="icon-button" aria-label="Notifications" data-action="notifications">♧<i class="notification-dot"></i></button><span class="top-divider"></span><button class="avatar top-avatar" data-action="profile">${initials(user.name)}</button></div></header><div class="content">${active==='Dashboard' ? dashboard() : renderSection(active)}</div></main></div><div id="modal-root"></div><div id="toast-root"></div>`;
  bind();
  enhanceToolUploads();
  if (tools.some(tool => tool.name === active)) enhanceRecentCreations();
  if (active === 'Dashboard') enhanceDashboardSubjects();
  if (active === 'Study Planner') enhanceStudyPlannerSubjects();
  if (active === 'Exam Prep Planner') enhancePlannerTimetable();
  if (active === 'My Library') enhanceUploadedLibrary();
}
function initials(s:string){return s.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}
async function loadSubjects(){const response=await fetch('/api/subjects');if(!response.ok)throw new Error('Could not load your subjects.');const result=await response.json() as {subjects?:Subject[]};subjects=result.subjects||[]}
async function loadStats(){const response=await fetch('/api/activity');if(!response.ok)throw new Error('Could not load your study activity.');stats=await response.json() as ActivityStats}
async function recordActivity(type:'study_session'|'quiz_generated',durationMinutes=0,subject=''){const response=await fetch('/api/activity',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type,durationMinutes,subject})});if(!response.ok)throw new Error('Could not save your study activity.');await loadStats()}
type Creation={id:string;title:string;content:string;createdAt:string};
async function saveCreation(tool:string,content:string){const title=content.split(/\r?\n/).map(line=>line.replace(/^#+\s*/, '').replace(/\*\*/g,'').trim()).find(Boolean)?.slice(0,100)||'Study work';const response=await fetch('/api/creations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tool,title,content})});if(!response.ok)throw new Error('Your result was made, but could not be saved to Recently created.');}
function enhanceRecentCreations(){const tool=tools.find(item=>item.name===active);const panel=app.querySelector<HTMLDivElement>('.recent-card .recent-empty');if(!tool||!panel)return;panel.textContent='Loading your recent work…';fetch(`/api/creations?tool=${encodeURIComponent(tool.id)}`).then(async response=>{const data=await response.json() as {creations?:Creation[];error?:string};if(!response.ok)throw new Error(data.error||'Could not load recent work.');const creations=data.creations||[];if(!creations.length){panel.innerHTML='<span>◷</span><p>Your work will show up here after you generate it.</p>';return}panel.classList.add('recent-creation-list');panel.innerHTML=creations.map((creation,index)=>`<button class="recent-creation" type="button" data-creation-index="${index}"><b>${esc(creation.title)}</b><small>${new Date(creation.createdAt).toLocaleString()}</small></button>`).join('');panel.addEventListener('click',event=>{const button=(event.target as HTMLElement).closest<HTMLButtonElement>('[data-creation-index]');if(!button)return;const creation=creations[Number(button.dataset.creationIndex)];const result=app.querySelector<HTMLDivElement>('#result-area');if(result)result.innerHTML=`<article class="panel result-panel"><div class="result-top"><span class="quick-icon lavender">✧</span><div><b>${esc(creation.title)}</b><small>Saved study work</small></div><button class="select-pill" data-action="copy-saved">Copy text</button></div><div class="result-content">${formatMarkdown(creation.content)}</div></article>`;result?.querySelector('[data-action="copy-saved"]')?.addEventListener('click',()=>navigator.clipboard.writeText(creation.content).then(()=>toast('Copied to clipboard.')));result?.scrollIntoView({behavior:'smooth',block:'start'})})}).catch(error=>{panel.textContent=(error as Error).message})}
function navItem(name:string, icon:string){return `<button class="nav-link ${active===name?'selected':''}" data-section="${name}"><span>${icon}</span>${name}</button>`}
function dashboard(){ return `<section class="welcome-row"><div><div class="eyebrow"><span class="live-dot"></span> ${new Intl.DateTimeFormat('en', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }).format(new Date()).toUpperCase()}</div><h1>Good morning, ${esc(user!.name.split(' ')[0])} <span class="wave">✳</span></h1><p class="welcome-sub">A fresh week, a fresh start. You’re doing great — keep it up.</p></div><button class="primary-button" data-tool="planner"><span>＋</span> Plan a study session</button></section>${subjectPanelMarkup()}<section class="stats-grid"><article class="stat-card"><div class="stat-heading"><span>Study time this week</span><span class="stat-icon peach">◷</span></div><div class="stat-value">${(stats.minutes_this_week/60).toFixed(1)} <small>hrs</small></div><div class="stat-foot"><span>${stats.minutes_this_week ? "Study time recorded" : "No study time yet"}</span><span>This week</span></div></article><article class="stat-card"><div class="stat-heading"><span>Current study streak</span><span class="stat-icon coral">♨</span></div><div class="stat-value">${stats.current_streak} <small>days</small></div><div class="stat-foot"><span>${stats.current_streak ? "Current streak" : "No streak yet"}</span></div></article><article class="stat-card"><div class="stat-heading"><span>AI quizzes generated</span><span class="stat-icon lavender">✳</span></div><div class="stat-value">${stats.quizzes_generated}</div><div class="stat-foot"><span>${stats.quizzes_generated ? "Quizzes you generated" : "No quizzes generated yet"}</span></div></article><article class="stat-card"><div class="stat-heading"><span>Study sessions</span><span class="stat-icon mint">✓</span></div><div class="stat-value">${stats.sessions_completed}<small> total</small></div><div class="stat-foot"><span>Completed sessions only</span></div></article></section><section class="middle-grid"><article class="panel performance-panel"><div class="panel-head"><div><h2>Your performance</h2><p>Look how far you’ve come ✨</p></div><button class="select-pill" data-action="period">This week <span>⌄</span></button></div><div class="chart-legend"><i></i> Quiz scores <small>·</small> <span>Based on your study activity</span></div><div class="chart-wrap"><div class="chart-y"><span>100%</span><span>75%</span><span>50%</span><span>25%</span><span>0%</span></div><div class="chart-main"><div class="chart-grid"><i></i><i></i><i></i><i></i><i></i></div><svg class="line-chart" viewBox="0 0 680 190" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#8372e9" stop-opacity=".18"/><stop offset="1" stop-color="#8372e9" stop-opacity="0"/></linearGradient></defs><path class="area-path" d="M0 138 C38 130 54 89 104 97 S172 122 208 84 S280 93 312 63 S380 82 416 52 S480 71 520 38 S590 61 632 25 S660 33 680 19 L680 190 L0 190Z"/><path class="line-path" d="M0 138 C38 130 54 89 104 97 S172 122 208 84 S280 93 312 63 S380 82 416 52 S480 71 520 38 S590 61 632 25 S660 33 680 19"/><circle cx="680" cy="19" r="5"/></svg><div class="chart-x"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span></div></div></div></article><article class="panel focus-panel"><div class="panel-head"><div><h2>Today’s focus</h2><p>Small steps add up.</p></div><button class="more-button" data-action="focus-menu">•••</button></div><div class="focus-progress"><div class="donut"><div><b>${stats.sessions_completed}</b><small>sessions</small></div></div><div><b>You're finding<br/>your rhythm!</b><small>${stats.sessions_completed} study sessions recorded</small></div></div><div class="focus-divider"></div><div class="task-list"><div class="task-row"><button class="task-check checked" data-task="done">✓</button><div><b>Review organic chemistry</b><small>Biology · 45 min</small></div><span class="task-tag tag-done">Done</span></div><div class="task-row"><button class="task-check" data-task="pending"></button><div><b>Complete calculus quiz</b><small>Mathematics · 30 min</small></div><span class="task-tag tag-next">Up next</span></div></div><button class="text-button" data-section="Study Planner">See full schedule <span>→</span></button></article></section><section class="bottom-grid"><article class="panel upcoming-panel"><div class="panel-head"><div><h2>Coming up</h2><p>Your next few study sessions</p></div><button class="text-button" data-section="Study Planner">Full schedule <span>→</span></button></div><div class="session-list"><div class="session"><div class="date-tile"><b>14</b><small>OCT</small></div><div class="session-line purple-line"></div><div class="session-info"><b>Linear Algebra — Problem set</b><small><span>◷</span> 10:30 AM · 45 min <i>•</i> Mathematics</small></div><button class="session-action" data-action="start-session">Start <span>→</span></button></div><div class="session"><div class="date-tile"><b>14</b><small>OCT</small></div><div class="session-line green-line"></div><div class="session-info"><b>Biology — Cell structure review</b><small><span>◷</span> 2:00 PM · 30 min <i>•</i> Biology</small></div><button class="session-action" data-action="start-session">Start <span>→</span></button></div><div class="session"><div class="date-tile"><b>15</b><small>OCT</small></div><div class="session-line peach-line"></div><div class="session-info"><b>English — Essay outline</b><small><span>◷</span> 9:00 AM · 50 min <i>•</i> English</small></div><button class="session-action" data-action="start-session">Start <span>→</span></button></div></div></article><article class="panel quick-panel"><div class="panel-head"><div><h2>Quick tools</h2><p>Jump back in where you need</p></div><button class="more-button" data-action="tools-menu">•••</button></div><div class="quick-grid">${tools.slice(0,4).map(t=>`<button class="quick-tool" data-tool="${t.id}"><span class="quick-icon ${t.color}">${t.icon}</span><span><b>${t.name}</b><small>${t.description}</small></span><span class="quick-arrow">↗</span></button>`).join('')}</div></article></section><footer class="footer-note">Made for your next big thing <span>✳</span></footer>` }
function renderSection(name:string){ if(name==='Study Planner')return plannerPage(); if(name==='Progress')return progressPage(); if(name==='My Library')return libraryPage(); const tool=tools.find(t=>t.name===name); if(tool)return toolPage(tool); return `<div class="section-heading"><div class="eyebrow">YOUR LEARNOVA</div><h1>${esc(name)}</h1><p>Your study space, set up around you.</p></div><article class="panel empty-state"><span class="empty-illustration">✳</span><h2>Everything in one calm place</h2><p>Pick a study tool from the sidebar to get started.</p><button class="primary-button" data-section="Dashboard">Back to dashboard →</button></article>` }
function plannerPage(){return `<div class="section-heading"><div class="eyebrow">MAKE SPACE FOR WHAT MATTERS</div><h1>Your study planner <span class="wave">▦</span></h1><p>A flexible plan that keeps your goals in sight.</p></div><div class="planner-layout"><article class="panel week-panel"><div class="panel-head"><div><h2>This week</h2><p>October 14 – 20, 2024</p></div><button class="select-pill" data-tool="planner">✳ Make me a plan</button></div><div class="week-days">${['Mon 14','Tue 15','Wed 16','Thu 17','Fri 18','Sat 19','Sun 20'].map((d,i)=>`<div class="week-day ${i===0?'today':''}"><small>${d.split(' ')[0]}</small><b>${d.split(' ')[1]}</b><div class="day-dot ${i<3?'has-event':''}"></div></div>`).join('')}</div><div class="planner-session"><span class="session-line purple-line"></span><div><b>Linear Algebra — Problem set</b><small>10:30 AM · 45 min</small></div><span class="subject-chip">Mathematics</span><button class="session-action" data-action="start-session">Start →</button></div><div class="planner-session"><span class="session-line green-line"></span><div><b>Biology — Cell structure review</b><small>2:00 PM · 30 min</small></div><span class="subject-chip">Biology</span><button class="session-action" data-action="start-session">Start →</button></div><button class="add-session" data-action="add-session">＋ Add a study session</button></article><article class="panel planner-side"><span class="stat-icon lavender">✦</span><h2>Your week, at a glance</h2><p>Two focused sessions today. You’ve got this.</p><div class="goal-row"><span>Weekly study goal</span><b>12.5 / 15 hrs</b></div><div class="progress-line"><span style="width:83%"></span></div><button class="primary-button full" data-tool="planner">Build my study plan</button></article></div><div class="pomodoro panel"><div><span class="eyebrow">A LITTLE FOCUS GOES A LONG WAY</span><h2>Pomodoro timer</h2><p>Focus for 25 minutes, then take a break.</p></div><div class="timer-display" id="timer-display">${formatTime(timerSeconds)}</div><button class="primary-button" data-action="timer">${timer?'Pause focus':'Start focus'} <span>→</span></button></div>`}
function formatTime(n:number){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function startPomodoro(){timerSeconds=25*60;timerStartedAt=Date.now();timer=window.setInterval(()=>{timerSeconds=Math.max(0,timerSeconds-1);const display=document.querySelector('#timer-display');if(display)display.textContent=formatTime(timerSeconds);if(timerSeconds===0){clearInterval(timer);timer=undefined;void recordActivity('study_session',25,focusSubject).then(()=>{toast('25-minute study session recorded.');render()}).catch(error=>toast((error as Error).message));}},1000)}
async function pausePomodoro(){if(!timer)return;clearInterval(timer);timer=undefined;const elapsed=Math.floor((Date.now()-timerStartedAt)/60000);if(elapsed>0){try{await recordActivity('study_session',elapsed,focusSubject);toast(`${elapsed} study minute${elapsed===1?'':'s'} recorded.`)}catch(error){toast((error as Error).message)}}timerSeconds=25*60;render()}
function progressPage(){return `<div class="section-heading"><div class="eyebrow">YOUR LEARNING ACTIVITY</div><h1>Your progress <span class="wave">↗</span></h1><p>Only activity you complete in Learnova is counted here.</p></div><div class="stats-grid progress-stats"><article class="stat-card"><div class="stat-heading">Study time this week<span class="stat-icon peach">◷</span></div><div class="stat-value">${(stats.minutes_this_week/60).toFixed(1)}<small> hrs</small></div><div class="stat-foot">From completed focus sessions</div></article><article class="stat-card"><div class="stat-heading">Current streak<span class="stat-icon coral">♨</span></div><div class="stat-value">${stats.current_streak}<small> days</small></div><div class="stat-foot">Consecutive days with a completed session</div></article><article class="stat-card"><div class="stat-heading">AI quizzes generated<span class="stat-icon lavender">✳</span></div><div class="stat-value">${stats.quizzes_generated}</div><div class="stat-foot">Successfully generated quizzes</div></article><article class="stat-card"><div class="stat-heading">Study sessions<span class="stat-icon mint">✓</span></div><div class="stat-value">${stats.sessions_completed}</div><div class="stat-foot">Completed focus sessions</div></article></div><article class="panel insight-panel"><span class="stat-icon lavender">✧</span><div><h2>Your activity</h2><p>${stats.sessions_completed||stats.quizzes_generated?`${stats.sessions_completed} completed study sessions and ${stats.quizzes_generated} generated quizzes recorded.`:'Nothing to report yet. Complete a focus session or generate a quiz and your real activity will show here.'}</p></div></article>`}function libraryPage(){return `<div class="section-heading"><div class="eyebrow">YOUR WORK, ALL TOGETHER</div><h1>My library <span class="wave">▤</span></h1><p>Your recent notes, quizzes, and study plans.</p></div><div class="library-toolbar"><label class="search library-search"><span>⌕</span><input placeholder="Search your library..." /></label><button class="select-pill" data-action="filter">All items⌄</button><button class="primary-button" data-tool="notes">＋ Create something</button></div><div class="library-grid">${[{icon:'✳',n:'Cell Biology — practice quiz',s:'AI Quiz Maker · Today, 9:42 AM',c:'lavender'},{icon:'▤',n:'Photosynthesis — key concepts',s:'Notes Summarizer · Yesterday',c:'peach'},{icon:'▦',n:'Midterm revision plan',s:'Exam Prep Planner · Oct 10',c:'mint'},{icon:'✧',n:'Acing your study routine',s:'AI Study Advisor · Oct 8',c:'blue'}].map(x=>`<button class="library-card" data-action="library-item"><span class="quick-icon ${x.c}">${x.icon}</span><span class="library-copy"><b>${x.n}</b><small>${x.s}</small></span><span class="quick-arrow">↗</span></button>`).join('')}</div>`}
function toolPage(t:Tool){return `<div class="section-heading"><div class="eyebrow">YOUR AI STUDY TOOLKIT</div><h1>${t.name} <span class="wave">${t.icon}</span></h1><p>${t.description}. Just tell Learnova what you’re working on.</p></div><div class="tool-layout"><article class="panel tool-form"><div class="tool-label"><span class="quick-icon ${t.color}">${t.icon}</span><div><b>Let’s get started</b><small>More detail helps us make something that fits you.</small></div></div>${t.id==='transcript'?`<label class="field-label">Video link<input id="tool-link" class="text-input" placeholder="https://www.youtube.com/watch?v=..." /></label><div class="info-callout">ⓘ For accurate transcripts, include captions or paste the transcript text below. YouTube links alone may not provide accessible video audio.</div><label class="field-label">Transcript text <span class="optional">Optional, for accurate results</span><textarea id="tool-input" rows="7" placeholder="Paste captions or transcript text here…"></textarea></label>`:`<label class="field-label">${t.id==='advisor'?'What’s on your mind?':'Your study material'}<textarea id="tool-input" rows="9" placeholder="${t.placeholder}"></textarea></label>`}<div class="tool-controls"><label class="field-label compact">${t.id==='quiz'?'Number of questions':t.id==='planner'?'Exam date':'Output style'}<select id="tool-option" class="text-input">${(t.id==='quiz'?['5 questions','10 questions','15 questions']:t.id==='planner'?['In 1 week','In 2 weeks','In 1 month']:['Clear & concise','Detailed','Step by step']).map(o=>`<option>${o}</option>`).join('')}</select></label><button class="primary-button generate-button" data-action="generate" data-id="${t.id}"><span>✧</span> ${t.id==='advisor'?'Ask Learnova':'Generate with AI'} <span>→</span></button></div><div class="privacy-note">✦ Powered by Gemini <span>·</span> Your study materials stay yours</div></article><aside class="tool-aside"><article class="panel tip-card"><span class="tip-spark">✦</span><div class="eyebrow">A LITTLE TIP</div><h3>${t.id==='quiz'?'Test yourself, don’t just reread':t.id==='transcript'?'Good captions make great notes':t.id==='planner'?'The best plan has breathing room':'A little context goes a long way'}</h3><p>${t.id==='quiz'?'Try answering each question before revealing the key — active recall helps ideas stick.':t.id==='transcript'?'Paste the video captions below its link to get a clean and accurate transcript.':'Add your goals and available time for a result that really fits your week.'}</p></article><article class="panel recent-card"><div class="panel-head"><div><h3>Recently created</h3><p>Your latest ${t.name.toLowerCase()} work</p></div></div><div class="recent-empty"><span>◷</span><p>Your work will show up here after you generate it.</p></div></article></aside></div><div id="result-area"></div>`}
function renderAuth(){app.innerHTML=`<main class="auth-screen"><div class="auth-art"><a class="brand" href="#"><span class="brand-mark">✳</span><span>learnova<span class="brand-period">.</span></span></a><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-center"><div class="art-sun">✳</div><span class="float-card float-card-a">✦ &nbsp; A little progress, every day</span><span class="float-card float-card-b">↗ &nbsp; You’re doing great!</span></div><div class="art-caption"><h2>Your next big thing<br/>starts with one small step.</h2><p>A calmer, more personal way to make learning click.</p></div><div class="art-dots">● &nbsp; ○ &nbsp; ○</div></div><div class="auth-main"><button class="auth-help" data-action="help">Need a hand? <b>Get in touch ↗</b></button><div class="auth-box"><div class="auth-mobile-brand brand"><span class="brand-mark">✳</span> learnova<span class="brand-period">.</span></div><div class="auth-welcome"><span class="eyebrow">YOUR STUDY SPACE IS WAITING</span><h1>${authMode==='signup'?'Make it yours.':'Welcome back.'}</h1><p>${authMode==='signup'?'Create your account and take the next step.':'Pick up right where you left off.'}</p></div><div class="auth-tabs"><button class="${authMode==='login'?'active':''}" data-auth-mode="login">Log in</button><button class="${authMode==='signup'?'active':''}" data-auth-mode="signup">Create account</button></div><form id="auth-form">${authMode==='signup'?`<label class="field-label">Your name<input class="text-input" name="name" required placeholder="What should we call you?" /></label>`:''}<label class="field-label">Email address<input class="text-input" type="email" name="email" required placeholder="you@example.com" /></label><label class="field-label">Password<input class="text-input" type="password" name="password" required minlength="8" placeholder="At least 8 characters" /></label>${authMode==='login'?`<div class="forgot-row"><label><input type="checkbox" /> Remember me</label><button type="button" data-action="forgot">Forgot password?</button></div>`:`<p class="terms-copy">By creating an account, you agree to our <a href="#">Terms</a> and <a href="#">Privacy Policy</a>.</p>`}<button class="primary-button auth-submit" type="submit">${authMode==='signup'?'Create my account':'Log in to Learnova'} <span>→</span></button></form><p class="auth-switch">${authMode==='signup'?'Already have an account?':'New to Learnova?'} <button data-auth-mode="${authMode==='signup'?'login':'signup'}">${authMode==='signup'?'Log in':'Create an account'}</button></p><div class="auth-secure">♢ &nbsp; Your learning journey is private and secure</div></div><footer class="auth-footer">© 2024 Learnova <span>·</span> Made for curious minds <span>✳</span></footer></div></main><div id="toast-root"></div>`; app.querySelector('#auth-form')?.addEventListener('submit',submitAuth); app.querySelectorAll<HTMLElement>('[data-auth-mode]').forEach(b=>b.onclick=()=>{authMode=b.dataset.authMode as 'login'|'signup';render()});app.querySelector('[data-action="forgot"]')?.addEventListener('click',()=>toast('Password reset will be available when email is configured.')); app.querySelector('[data-action="help"]')?.addEventListener('click',()=>toast('Email hello@learnova.app for help.')) }
let authMode:'login'|'signup'='signup';
async function parseAuthResponse(response:Response){const text=await response.text();let result:{user?:{name:string;email:string};error?:string};try{result=text?JSON.parse(text):{}}catch{throw new Error('The account service returned an unexpected response. Please retry shortly; if it continues, check the latest Vercel function logs.')}if(!response.ok)throw new Error(result.error||'Account request failed ('+response.status+').');return result}
async function submitAuth(e:Event){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget as HTMLFormElement));try{const r=await fetch('/api/auth/'+authMode,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const j=await parseAuthResponse(r);user=j.user||null;await loadSubjects().catch(()=>{subjects=[]});await loadStats().catch(()=>{});render()}catch(err){toast((err as Error).message==='Failed to fetch'?'Start the Learnova server to create your account.':(err as Error).message)}}
function bind(){app.querySelectorAll<HTMLElement>('[data-section]').forEach(b=>b.onclick=()=>{active=b.dataset.section!;if(active==='Dashboard')void loadStats().catch(()=>{}).finally(render);else render()});app.querySelectorAll<HTMLElement>('[data-tool]').forEach(b=>b.onclick=()=>{active=tools.find(t=>t.id===b.dataset.tool)?.name||active;render()});app.querySelectorAll<HTMLElement>('[data-action]').forEach(b=>b.onclick=()=>handleAction(b));}
function enhanceToolUploads(){
  const form=app.querySelector<HTMLFormElement>('.tool-form');
  if(!form||form.querySelector('.pdf-upload-card'))return;
  const card=document.createElement('div');card.className='pdf-upload-card';
  card.innerHTML=`<div class="pdf-upload-copy"><span class="quick-icon rose">▤</span><span><b>Add a PDF to your study session</b><small>Private upload · PDF up to 10 MB</small></span></div><input id="pdf-input" type="file" accept="application/pdf,.pdf" /><div class="pdf-upload-actions"><label class="select-pill" for="pdf-input">Choose PDF</label><button class="session-action" type="button" data-upload-pdf>Upload PDF</button></div>${activeDocument?`<div class="selected-document"><span>✓ &nbsp; ${esc(activeDocument.filename)}</span><button type="button" data-clear-pdf>Remove</button></div>`:''}`;
  form.insertBefore(card,form.querySelector('.tool-controls'));
  card.querySelector<HTMLButtonElement>('[data-upload-pdf]')!.onclick=()=>void uploadPdf();
  card.querySelector<HTMLButtonElement>('[data-clear-pdf]')?.addEventListener('click',()=>{activeDocument=null;render()});
}
async function uploadPdf(){
  const input=document.querySelector<HTMLInputElement>('#pdf-input');const file=input?.files?.[0];
  if(!file){toast('Choose a PDF file first.');return}
  if(file.size>10*1024*1024){toast('PDFs must be smaller than 10 MB.');return}
  const button=document.querySelector<HTMLButtonElement>('[data-upload-pdf]');if(button){button.disabled=true;button.textContent='Uploading…'}
  try{
    const response=await fetch('/api/files/upload-url',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:file.name,contentType:'application/pdf',size:file.size})});
    const signed=await response.json();if(!response.ok)throw Error(signed.error||'Could not prepare the PDF upload.');
    const contract=signed.upload as {method:'PUT'|'POST';url:string;headers?:Record<string,string>;fields?:Record<string,string>};
    let uploaded:Response;
    if(contract.method==='POST'){
      const data=new FormData();for(const [key,value] of Object.entries(contract.fields||{}))data.append(key,value);data.append('file',file);
      uploaded=await fetch(contract.url,{method:'POST',body:data});
    }else uploaded=await fetch(contract.url,{method:'PUT',headers:contract.headers,body:file});
    if(!uploaded.ok)throw Error('Neon could not store this PDF. Please try again.');
    const completedResponse=await fetch('/api/files/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:signed.id})});
    const completedJson=await completedResponse.json();if(!completedResponse.ok)throw Error(completedJson.error||'Could not finish saving the PDF.');
    activeDocument={id:completedJson.id,filename:completedJson.filename};render();toast('PDF saved privately to your library.');
  }catch(error){toast((error as Error).message||'PDF upload failed.')}finally{const current=document.querySelector<HTMLButtonElement>('[data-upload-pdf]');if(current){current.disabled=false;current.textContent='Upload PDF'}}
}
function localDateString(date = new Date()) { return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`; }
function refreshDashboardSubjectContent(){
  const taskList=app.querySelector<HTMLDivElement>('.task-list');
  if(taskList)taskList.innerHTML=subjects.length?subjects.slice(0,2).map((subject,index)=>`<div class="task-row"><span class="task-check "></span><div><b>${index===0?'Review':'Practice'} ${esc(subject.name)}</b><small>${esc(subject.name)} · 25 min</small></div><span class="task-tag tag-next">Suggested</span></div>`).join(''):'<div class="subject-empty"><b>No subjects added yet</b><small>Add your subjects above to personalize your focus.</small></div>';
  const sessionList=app.querySelector<HTMLDivElement>('.session-list');
  if(sessionList)sessionList.innerHTML=subjects.length?subjects.slice(0,3).map((subject,index)=>`<div class="session"><span class="session-line ${['purple-line','green-line','peach-line'][index]}"></span><div class="session-info"><b>${esc(subject.name)} study session</b><small>Suggested · 25 minutes</small></div><button class="session-action" data-action="start-session">Start <span>→</span></button></div>`).join(''):'<div class="subject-empty"><b>Your study sessions will start here</b><small>Add subjects above, then choose a subject for a focused session.</small></div>';
  const header=app.querySelector('.upcoming-panel .panel-head');const title=header?.querySelector('h2');if(title)title.textContent=subjects.length?'Study by subject':'Your study subjects';const sub=header?.querySelector('p');if(sub)sub.textContent=subjects.length?'Pick a subject to start a focused session.':'Add subjects to personalize your study space.';
  const focus=app.querySelector('.focus-panel .panel-head p');if(focus)focus.textContent=subjects.length?'Choose a subject and take one small step.':'Your subjects will shape your daily focus.';
  sessionList?.querySelectorAll<HTMLButtonElement>('[data-action="start-session"]').forEach((button,index)=>button.onclick=()=>{focusSubject=subjects[index]?.name||'';handleAction(button)});
}
function subjectPanelMarkup(){return `<section class="panel subjects-panel"><div class="subjects-panel-head"><div><h2>Your subjects</h2><p>Add subjects one at a time. Learnova will use them across your dashboard and study tools.</p></div><span class="subject-count">${subjects.length} added</span></div><form class="subject-add-form"><label class="sr-only" for="subject-name">Subject name</label><input id="subject-name" class="text-input" maxlength="80" placeholder="Type a subject name" autocomplete="off" required /><button class="primary-button" type="submit">＋ Add subject</button></form><div class="subject-chip-list">${subjects.length?subjects.map(subject=>`<span class="subject-chip-item">${esc(subject.name)}<button type="button" data-remove-subject="${esc(subject.id)}" aria-label="Remove ${esc(subject.name)}">×</button></span>`).join(''):'<p class="subject-empty-inline">No subjects yet. Add your first subject above.</p>'}</div></section>`}
function enhanceDashboardSubjects(){
  const panel=app.querySelector<HTMLElement>('.subjects-panel');if(!panel)return;
  panel.querySelector<HTMLFormElement>('.subject-add-form')?.addEventListener('submit',async event=>{
    event.preventDefault();const input=panel.querySelector<HTMLInputElement>('#subject-name')!;const name=input.value.trim();if(!name)return;
    const button=panel.querySelector<HTMLButtonElement>('button[type="submit"]')!;button.disabled=true;
    try{const response=await fetch('/api/subjects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});const result=await response.json() as {subject?:Subject;error?:string;exists?:boolean};if(!response.ok)throw new Error(result.error||'Could not add this subject.');if(result.subject&&!subjects.some(subject=>subject.id===result.subject!.id))subjects=[...subjects,result.subject];render();toast(result.exists?'That subject is already on your list.':'Subject added to your study space.');}
    catch(error){toast((error as Error).message)}finally{button.disabled=false;}
  });
  panel.querySelector<HTMLDivElement>('.subject-chip-list')?.addEventListener('click',async event=>{
    const button=(event.target as HTMLElement).closest<HTMLButtonElement>('[data-remove-subject]');if(!button)return;
    try{const response=await fetch(`/api/subjects?id=${encodeURIComponent(button.dataset.removeSubject!)}`,{method:'DELETE'});const result=await response.json() as {error?:string};if(!response.ok)throw new Error(result.error||'Could not remove this subject.');subjects=subjects.filter(subject=>subject.id!==button.dataset.removeSubject);render();toast('Subject removed.');}
    catch(error){toast((error as Error).message)}
  });
  refreshDashboardSubjectContent();
}
function plannerExamRowMarkup(){
  return `<div class="exam-row"><label><span>Subject</span><input class="text-input" data-exam-subject list="learnova-subject-list" maxlength="100" placeholder="Type or choose a subject" /></label><label><span>Exam date</span><input class="text-input" data-exam-date type="date" min="${localDateString()}" /></label><div class="exam-weekday"><span>Day</span><b data-exam-weekday>Select a date</b></div><button class="exam-remove" type="button" data-remove-exam aria-label="Remove exam">×</button></div>`;
}
function enhanceStudyPlannerSubjects(){
  const week=app.querySelector<HTMLDivElement>('.week-panel');if(!week)return;
  const today=new Date();const monday=new Date(today);monday.setDate(today.getDate()-((today.getDay()+6)%7));const sunday=new Date(monday);sunday.setDate(monday.getDate()+6);const fmt=(date:Date)=>new Intl.DateTimeFormat('en',{month:'short',day:'numeric'}).format(date);
  const subtitle=week.querySelector('.panel-head p');if(subtitle)subtitle.textContent=`${fmt(monday)} – ${fmt(sunday)}, ${sunday.getFullYear()}`;
  const days=week.querySelector<HTMLDivElement>('.week-days');if(days)days.innerHTML=Array.from({length:7},(_,index)=>{const date=new Date(monday);date.setDate(monday.getDate()+index);return `<div class="week-day ${localDateString(date)===localDateString()?'today':''}"><small>${new Intl.DateTimeFormat('en',{weekday:'short'}).format(date)}</small><b>${date.getDate()}</b><div class="day-dot"></div></div>`}).join('');
  week.querySelectorAll('.planner-session').forEach(item=>item.remove());
  const add=week.querySelector('.add-session');const rows=subjects.length?subjects.map((subject,index)=>`<div class="planner-session"><span class="session-line ${['purple-line','green-line','peach-line'][index%3]}"></span><div><b>${esc(subject.name)} study session</b><small>Choose this subject for focused practice</small></div><span class="subject-chip">${esc(subject.name)}</span><button class="session-action" data-action="start-session">Start →</button></div>`).join(''):`<div class="subject-empty"><b>Add your subjects to get started</b><small>Your study planner will use the subjects you add on the dashboard.</small><button class="text-button" data-section="Dashboard">Add subjects →</button></div>`;
  add?.insertAdjacentHTML('beforebegin',rows);
  week.querySelectorAll<HTMLElement>('[data-action="start-session"]').forEach((button,index)=>button.onclick=()=>{focusSubject=subjects[index]?.name||'';handleAction(button)});
  week.querySelectorAll<HTMLElement>('[data-section]').forEach(button=>button.onclick=()=>{active=button.dataset.section!;render()});
  const side=app.querySelector('.planner-side');const heading=side?.querySelector('h2');if(heading)heading.textContent='Your subjects';const note=side?.querySelector('p');if(note)note.textContent=subjects.length?`${subjects.length} subject${subjects.length===1?'':'s'} in your study space. Manage them from your dashboard.`:'Add subjects on your dashboard to personalize your study plan.';side?.querySelector('.goal-row')?.remove();side?.querySelector('.progress-line')?.remove();const sideButton=side?.querySelector<HTMLButtonElement>('.primary-button');if(sideButton){sideButton.textContent=subjects.length?'Manage my subjects':'Add my subjects';sideButton.dataset.section='Dashboard';sideButton.onclick=()=>{active='Dashboard';render()};}
}
function enhancePlannerTimetable(){
  const form=app.querySelector<HTMLDivElement>('.tool-form');if(!form||form.querySelector('.exam-planner-form'))return;
  const heading=form.querySelector('.tool-label small');if(heading)heading.textContent='Add each subject and its scheduled exam date.';
  const intro=app.querySelector<HTMLParagraphElement>('.section-heading>p');if(intro)intro.textContent='Enter your exam timetable. Learnova will build a day-by-day study plan around it.';
  const oldInput=form.querySelector('#tool-input')?.closest('label');
  if(!oldInput)return;
  const planner=document.createElement('div');planner.className='exam-planner-form';
  planner.innerHTML=`<p class="exam-planner-instructions">Add your exams in any order. The weekday is filled in automatically.</p><div class="exam-row-headings"><span>Subject</span><span>Exam date</span><span>Day</span><span></span></div><div class="exam-rows">${plannerExamRowMarkup()}</div><datalist id="learnova-subject-list">${subjects.map(subject=>`<option value="${esc(subject.name)}"></option>`).join('')}</datalist><button class="add-exam-row" type="button" data-add-exam>＋ Add another exam</button><label class="field-label planner-notes-label">Topics or priorities <span class="optional">Optional</span><textarea id="planner-notes" rows="3" placeholder="List chapters, difficult topics, or other priorities…"></textarea></label><textarea id="tool-input" class="planner-prompt-data" aria-hidden="true" tabindex="-1"></textarea>`;
  oldInput.replaceWith(planner);
  const optionLabel=form.querySelector<HTMLLabelElement>('.tool-controls .field-label.compact');
  if(optionLabel)optionLabel.innerHTML=`Daily study time<select id="tool-option" class="text-input"><option>1 hour per day</option><option selected>2 hours per day</option><option>3 hours per day</option><option>4 hours per day</option><option>5 hours per day</option><option>6 hours per day</option></select>`;
  const tip=form.parentElement?.querySelector('.tip-card');
  const tipHeading=tip?.querySelector('h3');if(tipHeading)tipHeading.textContent='Enter every exam date';
  const tipBody=tip?.querySelector('p');if(tipBody)tipBody.textContent='Add each subject and its scheduled date. Learnova uses the exam order and time remaining to prioritize your revision.';
  const button=form.querySelector<HTMLButtonElement>('[data-action="generate"]');if(button){button.innerHTML='<span>✧</span> Build my study plan <span>→</span>';button.setAttribute('aria-label','Build my study plan');button.onclick=()=>generatePlanner();}
  const rows=planner.querySelector<HTMLDivElement>('.exam-rows')!;
  const refresh=()=>{
    const allRows=Array.from(rows.querySelectorAll<HTMLDivElement>('.exam-row'));
    for(const row of allRows){
      const date=row.querySelector<HTMLInputElement>('[data-exam-date]')!.value;
      const dayLabel=row.querySelector<HTMLElement>('[data-exam-weekday]')!;
      if(date){const [year,month,day]=date.split('-').map(Number);dayLabel.textContent=new Intl.DateTimeFormat('en',{weekday:'long'}).format(new Date(year,month-1,day));}
      else dayLabel.textContent='Select a date';
      const remove=row.querySelector<HTMLButtonElement>('[data-remove-exam]')!;remove.disabled=allRows.length===1;
    }
  };
  planner.addEventListener('input',refresh);planner.addEventListener('change',refresh);
  planner.addEventListener('click',event=>{
    const target=event.target as HTMLElement;
    if(target.closest('[data-add-exam]')){if(rows.querySelectorAll('.exam-row').length>=12){toast('Add up to 12 exams to one study plan.');return}rows.insertAdjacentHTML('beforeend',plannerExamRowMarkup());refresh();rows.querySelector<HTMLInputElement>('.exam-row:last-child [data-exam-subject]')?.focus();}
    if(target.closest('[data-remove-exam]')&&rows.querySelectorAll('.exam-row').length>1){target.closest('.exam-row')?.remove();refresh();}
  });
  refresh();
}
function generatePlanner(){
  const wrapper=app.querySelector<HTMLDivElement>('.exam-planner-form');const input=wrapper?.querySelector<HTMLTextAreaElement>('#tool-input');if(!wrapper||!input)return;
  const rows=Array.from(wrapper.querySelectorAll<HTMLDivElement>('.exam-row'));
  const exams=rows.map(row=>({subject:row.querySelector<HTMLInputElement>('[data-exam-subject]')!.value.trim(),date:row.querySelector<HTMLInputElement>('[data-exam-date]')!.value}));
  if(exams.some(exam=>!exam.subject||!exam.date)){toast('Enter a subject and exam date for every row.');return}
  if(!exams.length){toast('Add at least one exam to build your plan.');return}
  const today=localDateString();if(exams.some(exam=>exam.date<today)){toast('Exam dates must be today or later.');return}
  exams.sort((a,b)=>a.date.localeCompare(b.date));
  const dailyTime=wrapper.closest('.tool-form')?.querySelector<HTMLSelectElement>('#tool-option')?.value||'2 hours per day';
  const timetable=exams.map(exam=>{const [year,month,day]=exam.date.split('-').map(Number);const weekday=new Intl.DateTimeFormat('en',{weekday:'long'}).format(new Date(year,month-1,day));return `- ${exam.subject}: ${weekday}, ${exam.date}`}).join('\n');
  const notes=wrapper.querySelector<HTMLTextAreaElement>('#planner-notes')?.value.trim();
  input.value=`Current date: ${today}\nAvailable study time: ${dailyTime}\nExam timetable (in chronological order):\n${timetable}${notes?`\n\nTopics and priorities:\n${notes}`:''}`;
  void generate('planner');
}
function enhanceUploadedLibrary(){
  const content=app.querySelector<HTMLDivElement>('.content');if(!content||content.querySelector('.uploaded-documents'))return;
  const grid=content.querySelector<HTMLDivElement>('.library-grid');if(grid)grid.innerHTML='<article class="panel library-empty"><h2>Your study library is ready</h2><p>Uploaded PDFs appear below. Your subjects are managed from the dashboard.</p></article>';
  const panel=document.createElement('article');panel.className='panel uploaded-documents';panel.innerHTML='<div class="panel-head"><div><h2>Uploaded PDFs</h2><p>Your private study documents</p></div></div><div class="uploaded-files-list" id="uploaded-files">Loading your files…</div>';
  content.append(panel);
  fetch('/api/files/list').then(async response=>{const result=await response.json();if(!response.ok)throw Error(result.error||'Could not load your PDFs.');const list=panel.querySelector<HTMLDivElement>('#uploaded-files')!;list.innerHTML=result.files.length?result.files.map((file:{id:string;filename:string;size:number;createdAt:string})=>`<div class="uploaded-file-row"><span class="quick-icon rose">▤</span><span><b>${esc(file.filename)}</b><small>${(file.size/1024).toFixed(0)} KB · ${new Date(file.createdAt).toLocaleDateString()}</small></span><a class="session-action" href="/api/files/download?id=${encodeURIComponent(file.id)}" target="_blank" rel="noopener">Open PDF →</a></div>`).join(''):'<p class="recent-empty">No PDFs uploaded yet. Add one from any study tool.</p>'}).catch(error=>{const list=panel.querySelector<HTMLDivElement>('#uploaded-files');if(list)list.textContent=(error as Error).message});
}
function handleAction(b:HTMLElement){const a=b.dataset.action;if(a==='timer'){if(timer)void pausePomodoro();else{startPomodoro();b.textContent='Pause focus'}}else if(a==='start-session'){focusSubject=b.dataset.subject||'';showModal('Ready when you are','A focused 25-minute session is a lovely place to start.',`<button class="primary-button" data-modal-action="start">Start focus session →</button>`)}else if(a==='add-session'){showModal('Add a study session','A small session is still a good session.',`<label class="field-label">What are you studying?${subjects.length?`<select class="text-input">${subjects.map(subject=>`<option value="${esc(subject.name)}">${esc(subject.name)}</option>`).join('')}</select>`:`<p class="subject-empty-inline">Add subjects on your dashboard first.</p>`}</label><label class="field-label">How long?<select class="text-input"><option>25 minutes</option><option>45 minutes</option><option>60 minutes</option></select></label><button class="primary-button" data-modal-action="add">Add session →</button>`)}else if(a==='generate')generate(b.dataset.id!);else if(a==='profile')showModal('Your profile',`${esc(user!.name)} · ${esc(user!.email)}`,`<button class="text-button" data-modal-action="logout">Log out →</button>`);else if(a==='settings')showModal('Settings','Make Learnova feel like yours.',`<p class="settings-line">Gemini AI status <span>Connect a server API key</span></p><p class="settings-line">Account <span>${esc(user!.email)}</span></p><button class="text-button" data-modal-action="logout">Log out →</button>`);else if(a==='notifications'||a==='period'||a==='tools-menu'||a==='focus-menu'||a==='filter'||a==='library-item'||a==='upgrade')toast(({notifications:'You’re all caught up ✨',period:'Showing your progress for this week.', 'tools-menu':'Your tools are ready when you are.', 'focus-menu':'Your focus list is up to date.',filter:'Showing all your saved work.', 'library-item':'This saved item will be available in your library.',upgrade:'Learnova Plus is coming soon.'} as Record<string,string>)[a!]||'Coming soon ✨')}async function parseApiResponse(response:Response){const text=await response.text();let data:{text:string;error?:string};try{data=(text?JSON.parse(text):{}) as {text:string;error?:string}}catch{if(response.status===504)throw new Error('The PDF analysis took too long on the server. Try a smaller PDF or retry in a moment.');if(response.status===413)throw new Error('The uploaded file or request is too large. Try a smaller PDF.');throw new Error(`The server returned an unreadable response (HTTP ${response.status}). Check the Vercel function logs, then try again.`)}if(!response.ok)throw new Error(data.error||`The server could not complete the request (HTTP ${response.status}).`);return data}async function generate(id:string){const t=tools.find(x=>x.id===id)!;const input=document.querySelector<HTMLInputElement|HTMLTextAreaElement>('#tool-input')?.value.trim();const link=document.querySelector<HTMLInputElement>('#tool-link')?.value.trim();if(!input&&!link&&!activeDocument){toast(id==='transcript'?'Add a video link or transcript text first.':'Add a little context or upload a PDF first — it helps Learnova help you.');return}const button=document.querySelector<HTMLButtonElement>('[data-action="generate"]');if(!button)return;button.disabled=true;button.innerHTML='<span class="spinner"></span> Working on it…';const result=document.querySelector<HTMLDivElement>('#result-area');result!.innerHTML=`<article class="panel result-panel"><div class="result-top"><span class="quick-icon ${t.color}">✧</span><div><b>Making something just for you</b><small>Learnova is thinking…</small></div></div><div class="loading-line"></div></article>`;try{const r=await fetch('/api/ai/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tool:id,prompt:t.prompt,content:[id!=='planner'&&subjects.length?`Student's registered subjects: ${subjects.map(subject=>subject.name).join(', ')}.`:'',link?`Video link: ${link}`:'',input||''].filter(Boolean).join('\n\n'),option:document.querySelector<HTMLSelectElement>('#tool-option')?.value,documentId:activeDocument?.id})});const j=await parseApiResponse(r);if(id==='quiz')void recordActivity('quiz_generated').catch(()=>{});try{await saveCreation(id,j.text);enhanceRecentCreations()}catch(saveError){toast((saveError as Error).message)}result!.innerHTML=`<article class="panel result-panel"><div class="result-top"><span class="quick-icon ${t.color}">✧</span><div><b>Your ${t.name.toLowerCase()}</b><small>Made with Learnova · just now</small></div><button class="select-pill" data-action="copy-result">Copy text</button></div><div class="result-content">${formatMarkdown(j.text)}</div></article>`;const copy=result!.querySelector('[data-action="copy-result"]');copy?.addEventListener('click',()=>navigator.clipboard.writeText(j.text).then(()=>toast('Copied to clipboard.'))); }catch(err){result!.innerHTML=`<article class="panel result-panel error-result"><div class="result-top"><span class="quick-icon rose">!</span><div><b>We couldn’t make that just yet</b><small>${esc((err as Error).message)}</small></div></div><p>Review the message above, then try again.</p></article>`}finally{button.disabled=false;button.innerHTML=`<span>✧</span> ${id==='advisor'?'Ask Learnova':'Generate with AI'} <span>→</span>`}}
function showModal(title:string,body:string,extra:string){const root=document.querySelector<HTMLDivElement>('#modal-root')!;root.innerHTML=`<div class="modal-backdrop"><section class="modal"><button class="modal-close" data-modal-action="close">×</button><div class="eyebrow">LEARNOVA</div><h2>${title}</h2><p>${body}</p><div class="modal-extra">${extra}</div></section></div>`;root.querySelector('.modal-backdrop')?.addEventListener('click',e=>{if(e.target===e.currentTarget)root.innerHTML=''});root.querySelectorAll<HTMLElement>('[data-modal-action]').forEach(x=>x.onclick=()=>{const action=x.dataset.modalAction;if(action==='logout'){user=null;subjects=[];fetch('/api/auth/logout',{method:'POST'}).finally(render)}else if(action==='start'){root.innerHTML='';active='Study Planner';startPomodoro();render();toast('Focus session started.')}else if(action==='add'){root.innerHTML='';toast('Study session added to your plan.')}else root.innerHTML=''})}
function toast(message:string){const root=document.querySelector<HTMLDivElement>('#toast-root');if(!root)return;root.innerHTML=`<div class="toast"><span>✧</span>${esc(message)}</div>`;window.setTimeout(()=>{root.innerHTML=''},3000)}
fetch('/api/auth/me').then(r=>r.ok?r.json():null).then(async j=>{if(j?.user){user=j.user;await loadSubjects().catch(()=>{subjects=[]});await loadStats().catch(()=>{})}else subjects=[];render()}).catch(()=>render());
